-- Process-owned transport to the single off-main cache controller. The
-- service owns channel identities, a bounded outbox, deduplicated semantic
-- observations, and epoch and barrier bookkeeping only. It mirrors no
-- dependency graph, performs no producer hashing, filesystem traversal,
-- publication, recovery, or source-plan parsing, and never waits on a
-- channel: requests return cached ready/error observations, terminal
-- request/barrier/failure facts arrive as pushed controller events, and
-- process shutdown alone joins the controller thread.
--
-- Generated bytes arrive here as ordered installation packets: the initial
-- begin/entries/commit stream establishes the epoch's resident store, later
-- commits extend it in place, and a terminal observation is only exposed once
-- the sequence whose bytes it vouches for is installed.

local CacheFs = require("libs.storage.src.CacheFs")
local ResidentCache = require("libs.storage.src.ResidentCache")

local ORDINARY_PER_UPDATE = 8
local ABSORB_PER_UPDATE = 32
-- One installation part carries at most this many references.
local INSTALL_PART_ENTRIES = 128
-- Resident bytes carry the selected generation as their source identity; the
-- controller mints it for the base corpus and the store validates it.
local BASE_SOURCE_PREFIX = "base:"

local VALID_KINDS = {
  milestone = true,
  field = true,
  ["logical-field"] = true,
  cell = true,
  portrait = true,
  ["icon-page"] = true,
  ["battle-scene"] = true,
  ["audio-bank"] = true,
  pokedex = true,
  ["easy-chat"] = true,
  ["battle-effect"] = true,
  ["battle-presentation"] = true,
  ["battle-trainer-picture"] = true,
  ["battle-ball"] = true,
  ["battle-evolution"] = true,
  ["startup-walker"] = true,
  ["opening-scene"] = true,
}
local VALID_URGENCIES = { required = true, near = true, sweep = true }
local URGENCY_ORDER = { required = 0, near = 10, sweep = 100 }

---@class CacheService
---@field _threadHost table<string, function>
---@field _command table<string, function>
---@field _reply table<string, function>
---@field _worker table<string, unknown>?
---@field _started boolean
---@field _joined boolean
---@field _nextEpoch integer
---@field _liveEpoch integer?
---@field _retiring boolean
---@field _nextRequestId integer
---@field _nextBarrierId integer
---@field _records table<integer, table<string, unknown>> requestId -> record
---@field _byKey table<string, integer> epoch:key -> requestId
---@field _controls table<string, unknown>[] lifecycle commands awaiting emission
---@field _ordinary table<string, unknown>[] request/promote commands awaiting emission
---@field _barriers table<string, table<string, unknown>> "epoch:barrier" -> waiter
---@field _failure string? terminal controller failure, never restarted
---@field _generations table<integer, string> controller-derived generation token by epoch
---@field _sweepSent table<integer, boolean> epochs with queued warmup authorization
---@field _boot table<integer, table<string, unknown>> epoch-scoped boot-source observation
---@field _bootRequested table<integer, boolean> epochs with a queued boot gate
---@field _cache table<integer, CacheService.Installed> committed resident view by epoch
---@field _install table<integer, CacheService.Pending> installation in flight by epoch
---@field _pendingObservations table<integer, table<integer, table<string, unknown>>> terminal facts awaiting their sequence
---@field _firstPlayRequested table<integer, boolean> epochs whose first-play recording is already queued
---@field _versions table<integer, string> selected version id by epoch
local CacheService = {}
CacheService.__index = CacheService

---@class CacheService.Installed
---@field generationId string
---@field identity table<string, unknown>
---@field store ResidentCache
---@field reader CacheFs
---@field sequence integer
---@field firstPlay boolean
---@field milestones table<string, true>

---@class CacheService.Pending
---@field sequence integer
---@field generationId string
---@field identity table<string, unknown>
---@field entryCount integer
---@field parts ResidentCache.BatchEntry[][]

---@param value unknown
---@return boolean
local function isPositiveInteger(value)
  return type(value) == "number" and value % 1 == 0 and value >= 1
end

-- One resident reference as the controller published it. The data buffer is
-- compared by identity on purpose: a replayed part must carry the very bytes
-- the producer prepared, never a different buffer under one content id.
---@param first ResidentCache.BatchEntry
---@param second ResidentCache.BatchEntry
---@return boolean
local function sameEntry(first, second)
  return first.path == second.path
    and first.sourceId == second.sourceId
    and first.contentId == second.contentId
    and first.size == second.size
    and first.data == second.data
end

---@param options table<string, unknown>? { thread = love.thread-shaped host }
---@return CacheService
function CacheService.new(options)
  options = options or {}
  local host = options.thread
  if host == nil then
    local loveGlobal = rawget(_G, "love")
    host = loveGlobal and loveGlobal.thread
  end
  assert(
    type(host) == "table" and type(host.newChannel) == "function" and type(host.newThread) == "function",
    "cache service requires love.thread"
  )
  local command = assert(host.newChannel(), "cache service requires its command channel")
  local reply = assert(host.newChannel(), "cache service requires its reply channel")
  return setmetatable({
    _threadHost = host,
    _command = command,
    _reply = reply,
    _worker = nil,
    _started = false,
    _joined = false,
    _nextEpoch = 0,
    _liveEpoch = nil,
    _retiring = false,
    _nextRequestId = 0,
    _nextBarrierId = 0,
    _records = {},
    _byKey = {},
    _controls = {},
    _ordinary = {},
    _barriers = {},
    _generations = {},
    _failure = nil,
    _sweepSent = {},
    _boot = {},
    _bootRequested = {},
    _cache = {},
    _install = {},
    _pendingObservations = {},
    _firstPlayRequested = {},
    _versions = {},
  }, CacheService)
end

---@param versionId unknown
local function checkVersion(versionId)
  assert(type(versionId) == "string" and versionId ~= "", "cache selection requires a version")
end

---@param selector table<string, unknown>
---@return string dedup key for the semantic request
local function selectorKey(selector)
  assert(type(selector) == "table", "cache request requires its selectors")
  local kind = selector.requestKind
  assert(VALID_KINDS[kind], "unknown cache request kind: " .. tostring(kind))
  -- Observations may omit urgency: the dedup key never carries it, so a
  -- terminal event addresses the same record its request registered.
  local urgency = selector.urgency
  if urgency ~= nil then
    assert(VALID_URGENCIES[urgency], "unknown cache urgency: " .. tostring(urgency))
  end
  if kind == "milestone" then
    assert(type(selector.name) == "string" and selector.name ~= "", "milestone request requires its name")
    return "milestone:" .. selector.name
  elseif kind == "field" or kind == "logical-field" then
    assert(
      type(selector.mapId) == "number" and selector.mapId % 1 == 0 and selector.mapId >= 0,
      kind .. " request requires a non-negative integer mapId"
    )
    return kind .. ":" .. tostring(selector.mapId)
  elseif kind == "cell" then
    assert(
      type(selector.matrixMemberId) == "number" and selector.matrixMemberId % 1 == 0 and selector.matrixMemberId >= 0,
      "cell request requires a non-negative integer matrixMemberId"
    )
    assert(
      type(selector.index) == "number" and selector.index % 1 == 0 and selector.index >= 0,
      "cell request requires a non-negative integer index"
    )
    return "cell:" .. tostring(selector.matrixMemberId) .. ":" .. tostring(selector.index)
  elseif kind == "battle-scene" then
    assert(
      type(selector.sceneKey) == "string" and selector.sceneKey:match("^[^/]+/[^/]+/[^/]+$") ~= nil,
      "battle-scene request requires its background/terrain/time sceneKey"
    )
    return "battle-scene:" .. selector.sceneKey
  elseif kind == "audio-bank" then
    assert(
      type(selector.bankId) == "number" and selector.bankId % 1 == 0 and selector.bankId >= 0,
      "audio-bank request requires a non-negative integer bankId"
    )
    return "audio-bank:" .. tostring(selector.bankId)
  elseif kind == "pokedex" then
    assert(selector.pageId == nil, "pokedex request carries no page selector")
    assert(selector.name == nil, "pokedex request carries no milestone selector")
    assert(selector.mapId == nil, "pokedex request carries no map selector")
    assert(selector.matrixMemberId == nil, "pokedex request carries no cell selector")
    assert(selector.index == nil, "pokedex request carries no cell selector")
    assert(selector.sceneKey == nil, "pokedex request carries no scene selector")
    assert(selector.bankId == nil, "pokedex request carries no bank selector")
    assert(selector.trainerSelector == nil, "pokedex request carries no trainer selector")
    assert(selector.ballSelector == nil, "pokedex request carries no ball selector")
    return "pokedex"
  elseif kind == "easy-chat" then
    assert(selector.pageId == nil, "easy chat request carries no page selector")
    assert(selector.name == nil, "easy chat request carries no milestone selector")
    assert(selector.mapId == nil, "easy chat request carries no map selector")
    assert(selector.matrixMemberId == nil, "easy chat request carries no cell selector")
    assert(selector.index == nil, "easy chat request carries no cell selector")
    assert(selector.sceneKey == nil, "easy chat request carries no scene selector")
    assert(selector.bankId == nil, "easy chat request carries no bank selector")
    assert(selector.trainerSelector == nil, "easy chat request carries no trainer selector")
    assert(selector.ballSelector == nil, "easy chat request carries no ball selector")
    return "easy-chat"
  elseif kind == "battle-effect" then
    assert(
      type(selector.effectKey) == "string" and selector.effectKey ~= "" and selector.effectKey:find("/", 1, true) == nil,
      "battle-effect request requires its flat effectKey"
    )
    return "battle-effect:" .. selector.effectKey
  elseif kind == "battle-presentation" then
    for _, field in ipairs({
      "name",
      "mapId",
      "matrixMemberId",
      "index",
      "pageId",
      "sceneKey",
      "bankId",
      "effectKey",
      "trainerSelector",
      "ballSelector",
    }) do
      assert(selector[field] == nil, "battle-presentation request carries no " .. field .. " selector")
    end
    return "battle-presentation"
  elseif kind == "battle-trainer-picture" then
    -- Lua patterns have no alternation: capture the role stem, then
    -- require front/back explicitly. Syntax only; the producer proves
    -- catalog membership.
    local trainerRole, trainerClass
    if type(selector.trainerSelector) == "string" then
      trainerRole, trainerClass = selector.trainerSelector:match("^([a-z]+):([A-Z][A-Z0-9_]*)$")
    end
    assert(
      (trainerRole == "front" or trainerRole == "back") and trainerClass ~= nil,
      "battle-trainer-picture request requires its front:CLASS or back:CLASS trainerSelector"
    )
    for _, field in ipairs({
      "name",
      "mapId",
      "matrixMemberId",
      "index",
      "pageId",
      "sceneKey",
      "bankId",
      "effectKey",
      "ballSelector",
      "sceneNumber",
      "pairIndex",
    }) do
      assert(selector[field] == nil, "battle-trainer-picture request carries no " .. field .. " selector")
    end
    return "battle-trainer-picture:" .. selector.trainerSelector
  elseif kind == "battle-ball" then
    assert(
      type(selector.ballSelector) == "string" and selector.ballSelector:match("^ball:[A-Z][A-Z0-9_]*$") ~= nil,
      "battle-ball request requires its ball:ITEM ballSelector"
    )
    for _, field in ipairs({
      "name",
      "mapId",
      "matrixMemberId",
      "index",
      "pageId",
      "sceneKey",
      "bankId",
      "effectKey",
      "trainerSelector",
      "sceneNumber",
      "pairIndex",
    }) do
      assert(selector[field] == nil, "battle-ball request carries no " .. field .. " selector")
    end
    return "battle-ball:" .. selector.ballSelector
  elseif kind == "battle-evolution" then
    for _, field in ipairs({
      "name",
      "mapId",
      "matrixMemberId",
      "index",
      "pageId",
      "sceneKey",
      "bankId",
      "effectKey",
      "trainerSelector",
      "ballSelector",
      "sceneNumber",
      "pairIndex",
    }) do
      assert(selector[field] == nil, "battle-evolution request carries no " .. field .. " selector")
    end
    return "battle-evolution"
  elseif kind == "startup-walker" then
    assert(selector.pairIndex == nil, "startup-walker request carries no pair selector")
    for _, field in ipairs({
      "name",
      "mapId",
      "matrixMemberId",
      "index",
      "pageId",
      "sceneKey",
      "bankId",
      "trainerSelector",
      "ballSelector",
    }) do
      assert(selector[field] == nil, "startup-walker request carries no " .. field .. " selector")
    end
    return "startup-walker"
  elseif kind == "opening-scene" then
    assert(
      type(selector.sceneNumber) == "number"
        and selector.sceneNumber % 1 == 0
        and selector.sceneNumber >= 1
        and selector.sceneNumber <= 5,
      "opening-scene request requires an integer sceneNumber 1..5"
    )
    return "opening-scene:" .. tostring(selector.sceneNumber)
  else
    assert(
      type(selector.pageId) == "number" and selector.pageId % 1 == 0 and selector.pageId >= 0,
      kind .. " request requires a non-negative integer pageId"
    )
    return kind .. ":" .. tostring(selector.pageId)
  end
end

---@param options table<string, unknown> { versionId, development?, repositoryRoot? }
---@return integer? epoch, nil when the controller cannot select
function CacheService:select(options)
  assert(type(options) == "table", "cache selection requires its selectors")
  checkVersion(options.versionId)
  if self._failure ~= nil then
    return nil
  end
  local host = self._threadHost
  if not self._started then
    local Worker = require("romdump.src.build.CacheControllerWorker")
    local bootstrap = assert(Worker.bootstrap(), "cache controller has no thread entry")
    local worker = host.newThread(bootstrap)
    local started, startError = pcall(function()
      worker:start(self._command, self._reply, package.path)
    end)
    if not started then
      self._failure = "controller thread failed to start: " .. tostring(startError)
      return nil
    end
    self._worker = worker
    self._started = true
  end
  self._nextEpoch = self._nextEpoch + 1
  local epoch = self._nextEpoch
  self._liveEpoch = epoch
  self._retiring = false
  local command = {
    op = "select",
    epoch = epoch,
    versionId = options.versionId,
    development = options.development == true,
  }
  if options.repositoryRoot ~= nil then
    assert(type(options.repositoryRoot) == "string", "cache repository root must be a string")
    command.repositoryRoot = options.repositoryRoot
  end
  self._controls[#self._controls + 1] = command
  self._boot[epoch] = { state = "pending" }
  self._bootRequested[epoch] = nil
  self._versions[epoch] = options.versionId
  return epoch
end

-- Record (or strengthen) one semantic request. Only emission sends: repeats
-- for a pending record never queue another ensure command, and a
-- background-to-required strengthening queues a single promote for the
-- existing identity.
---@param epoch integer
---@param selector table<string, unknown>
---@return integer? request identity, nil for a stale epoch
function CacheService:request(epoch, selector)
  if type(epoch) ~= "number" or epoch ~= self._liveEpoch or self._retiring then
    return nil
  end
  if self._failure ~= nil then
    return nil
  end
  local key = selectorKey(selector)
  assert(VALID_URGENCIES[selector.urgency], "cache request requires its urgency")
  local mapKey = tostring(epoch) .. ":" .. key
  local existingId = self._byKey[mapKey]
  if existingId ~= nil then
    local record = assert(self._records[existingId], "cache request record is missing")
    if record.terminal then
      return existingId
    end
    local wanted = URGENCY_ORDER[selector.urgency]
    if wanted < URGENCY_ORDER[record.urgency] then
      record.urgency = selector.urgency
      if record.sent then
        self._ordinary[#self._ordinary + 1] =
          { op = "promote", epoch = epoch, requestId = existingId, urgency = "required" }
      else
        record.command.urgency = selector.urgency
      end
    end
    return existingId
  end
  self._nextRequestId = self._nextRequestId + 1
  local id = self._nextRequestId
  local command = {
    op = "request",
    epoch = epoch,
    requestId = id,
    requestKind = selector.requestKind,
    urgency = selector.urgency,
  }
  if selector.requestKind == "milestone" then
    command.name = selector.name
  elseif selector.requestKind == "field" or selector.requestKind == "logical-field" then
    command.mapId = selector.mapId
  elseif selector.requestKind == "cell" then
    command.matrixMemberId = selector.matrixMemberId
    command.index = selector.index
  elseif selector.requestKind == "battle-scene" then
    command.sceneKey = selector.sceneKey
  elseif selector.requestKind == "audio-bank" then
    command.bankId = selector.bankId
  elseif selector.requestKind == "pokedex" then
    -- The selector-free pokedex demand carries no job, source, page, or
    -- map identity: the dispatched packet names its kind and urgency only.
  elseif selector.requestKind == "easy-chat" then
    -- The selector-free easy chat demand carries no job, source, page, or
    -- map identity: the dispatched packet names its kind and urgency only.
  elseif selector.requestKind == "battle-effect" then
    command.effectKey = selector.effectKey
  elseif selector.requestKind == "battle-presentation" then
    -- The selector-free shared battle demand names its kind and urgency only.
  elseif selector.requestKind == "battle-trainer-picture" then
    command.trainerSelector = selector.trainerSelector
  elseif selector.requestKind == "battle-ball" then
    command.ballSelector = selector.ballSelector
  elseif selector.requestKind == "battle-evolution" then
    -- The selector-free evolution demand names its kind and urgency only.
  elseif selector.requestKind == "startup-walker" then
    -- The shared walker demand carries no pair identity.
  elseif selector.requestKind == "opening-scene" then
    command.sceneNumber = selector.sceneNumber
  else
    command.pageId = selector.pageId
  end
  self._records[id] = {
    id = id,
    epoch = epoch,
    key = key,
    selector = selector,
    urgency = selector.urgency,
    command = command,
    sent = false,
    terminal = false,
    ready = nil,
    failure = nil,
  }
  self._byKey[mapKey] = id
  local installed = self._cache[epoch]
  if selector.requestKind == "milestone" and installed ~= nil and installed.milestones[selector.name] then
    local record = assert(self._records[id], "cache request record is missing")
    record.terminal = true
    record.ready = true
    record.failure = nil
  else
    self._ordinary[#self._ordinary + 1] = command
  end
  return id
end

-- Cached observation only: never drains, sends, or waits. A retired epoch
-- grants no observation rights; a terminal controller failure reports its
-- cause instead of readiness.
---@param epoch integer
---@param selector table<string, unknown>
---@return boolean? ready
---@return string? failure
function CacheService:observe(epoch, selector)
  if type(epoch) ~= "number" or epoch ~= self._liveEpoch or self._retiring then
    return nil, nil
  end
  if self._failure ~= nil then
    return nil, self._failure
  end
  local key = selectorKey(selector)
  local id = self._byKey[tostring(epoch) .. ":" .. key]
  if id == nil then
    return nil, nil
  end
  local record = assert(self._records[id], "cache request record is missing")
  if record.terminal then
    if record.ready then
      return true, nil
    end
    return false, record.failure
  end
  return nil, nil
end

-- Cached controller-derived generation token for the epoch, or nil while
-- the selection answer is still in flight, the epoch is stale or retiring,
-- or the controller failed. Never scans, never waits: durability checks
-- treat an unknown generation as incomplete and prepare again.
---@param epoch integer
---@return string?
function CacheService:generationId(epoch)
  if type(epoch) ~= "number" or epoch ~= self._liveEpoch or self._retiring then
    return nil
  end
  if self._failure ~= nil then
    return nil
  end
  return self._generations[epoch]
end

-- Authorize lowest-priority background corpus completion for the epoch.
-- Idempotent per epoch: the controller authorization itself is idempotent
-- and performs no cache work in the call.
---@param epoch integer
function CacheService:enableSweep(epoch)
  if type(epoch) ~= "number" or epoch ~= self._liveEpoch or self._retiring then
    return
  end
  if self._failure ~= nil or self._sweepSent[epoch] then
    return
  end
  self._sweepSent[epoch] = true
  self._controls[#self._controls + 1] = { op = "enableSweep", epoch = epoch }
end

-- Retire the live epoch: observation rights end immediately while physical
-- retirement is acknowledged asynchronously through the exact barrier. The
-- installed resident view is revoked for new lookups here; buffers a consumer
-- already holds stay readable through their holders.
---@param epoch integer
---@return integer? barrier identity, nil for a stale epoch
function CacheService:retire(epoch)
  if type(epoch) ~= "number" or epoch ~= self._liveEpoch or self._retiring then
    return nil
  end
  self._retiring = true
  self._generations[epoch] = nil
  self._boot[epoch] = nil
  self._bootRequested[epoch] = nil
  self:_revokeEpoch(epoch)
  for position = #self._ordinary, 1, -1 do
    if self._ordinary[position].epoch == epoch then
      table.remove(self._ordinary, position)
    end
  end
  self._nextBarrierId = self._nextBarrierId + 1
  local barrier = self._nextBarrierId
  self._barriers[tostring(epoch) .. ":" .. tostring(barrier)] = { epoch = epoch, barrier = barrier, state = "pending" }
  self._controls[#self._controls + 1] = { op = "retire", epoch = epoch, barrierId = barrier }
  return barrier
end

-- Hand one validated immutable source buffer to the controller for the live
-- epoch. The game thread never opens the ROM itself: the import path
-- validated the bytes and the controller pins them to its selection. The
-- offer crosses by reference exactly once; stale, retired, or failed epochs
-- queue nothing, and a second offer for the same epoch is a programming
-- error only the caller can prevent.
---@param epoch integer selecting epoch, must be live
---@param byteData userdata the shared immutable buffer, passed by reference
---@param descriptor table<string, unknown> { versionId, romSha1 }
---@return boolean? true when the offer was queued, nil for a stale epoch
function CacheService:offerSource(epoch, byteData, descriptor)
  if type(epoch) ~= "number" or epoch ~= self._liveEpoch or self._retiring then
    return nil
  end
  if self._failure ~= nil then
    return nil
  end
  assert(type(byteData) == "userdata", "source handoff requires the shared buffer")
  assert(type(descriptor) == "table", "source handoff requires its version descriptor")
  assert(type(descriptor.versionId) == "string" and descriptor.versionId ~= "", "source handoff requires its version")
  assert(
    type(descriptor.romSha1) == "string" and #descriptor.romSha1 == 40,
    "source handoff requires its canonical identity"
  )
  self._controls[#self._controls + 1] = {
    op = "offer-source",
    epoch = epoch,
    byteData = byteData,
    versionId = descriptor.versionId,
    romSha1 = descriptor.romSha1,
  }
  return true
end

-- Queue the one boot-source gate behind selection and any source offer on
-- the same control FIFO. Idempotent for the live epoch: a duplicate call
-- registers nothing twice. Stale, retiring, or failed epochs queue nothing.
---@param epoch integer selecting epoch, must be live
---@return boolean? true when the gate is (or already was) queued, nil for a stale epoch
function CacheService:requestBootSource(epoch)
  if type(epoch) ~= "number" or epoch ~= self._liveEpoch or self._retiring then
    return nil
  end
  if self._failure ~= nil then
    return nil
  end
  if self._bootRequested[epoch] then
    return true
  end
  self._bootRequested[epoch] = true
  if self._boot[epoch] == nil then
    self._boot[epoch] = { state = "pending" }
  end
  self._controls[#self._controls + 1] = { op = "check-boot-source", epoch = epoch }
  return true
end

-- Cached boot-source observation only: never drains, sends, scans, or waits.
-- A retiring or stale epoch grants no observation rights; a terminal
-- controller failure reports its cause instead of readiness.
---@param epoch integer
---@return string? status "pending", "ready", "source-required", or "failed", nil for a stale epoch
---@return table<string, unknown>? detail typed { code, message, context? } cause on failure
function CacheService:bootSourceStatus(epoch)
  if type(epoch) ~= "number" or epoch ~= self._liveEpoch or self._retiring then
    return nil
  end
  if self._failure ~= nil then
    return "failed", { code = "CONTROLLER_FAILED", message = self._failure }
  end
  local record = self._boot[epoch]
  if record == nil then
    return nil
  end
  return record.state, record.detail
end

-- Ask the controller to close every worker source context so a later source
-- replacement cannot race a live reader. Import waits for the exact
-- acknowledgement, never for an empty queue or a timeout.
---@param epoch integer
---@return integer? barrier identity, nil for a stale epoch
function CacheService:quiesce(epoch)
  if type(epoch) ~= "number" then
    return nil
  end
  if epoch ~= self._liveEpoch and not self._retiring then
    return nil
  end
  if self._failure ~= nil then
    return nil
  end
  self._nextBarrierId = self._nextBarrierId + 1
  local barrier = self._nextBarrierId
  self._barriers[tostring(epoch) .. ":" .. tostring(barrier)] =
    { epoch = epoch, barrier = barrier, state = "pending", quiesce = true }
  self._controls[#self._controls + 1] = { op = "quiesce", epoch = epoch, barrierId = barrier }
  return barrier
end

---@param epoch integer
---@param barrier integer
---@return string? "pending", "ready", "failed", or nil for an unknown barrier
function CacheService:barrierStatus(epoch, barrier)
  local waiter = self._barriers[tostring(epoch) .. ":" .. tostring(barrier)]
  if waiter == nil then
    return nil
  end
  if waiter.state == "ready" then
    return "ready"
  end
  if self._failure ~= nil then
    return "failed"
  end
  return "pending"
end

-- Drop one epoch's installation stream, buffered terminal facts, and
-- resident view. Closing the store revokes new lookups only.
---@param epoch integer
function CacheService:_revokeEpoch(epoch)
  local installed = self._cache[epoch]
  if installed ~= nil then
    installed.store:close()
  end
  self._cache[epoch] = nil
  self._install[epoch] = nil
  self._pendingObservations[epoch] = nil
  self._firstPlayRequested[epoch] = nil
  self._versions[epoch] = nil
end

-- The epoch's one stable generated reader, available only after an
-- installation commit. A retired or unknown epoch hands out nothing, so a
-- consumer can never open a view the process no longer owns.
---@param epoch integer
---@return CacheFs?
function CacheService:getCacheFs(epoch)
  if type(epoch) ~= "number" or epoch ~= self._liveEpoch or self._retiring then
    return nil
  end
  local installed = self._cache[epoch]
  if installed == nil then
    return nil
  end
  return installed.reader
end

-- The full identity the installed bytes were produced under. A copy, so a
-- caller cannot mutate the epoch's record.
---@param epoch integer
---@return table<string, unknown>?
function CacheService:cacheIdentity(epoch)
  if type(epoch) ~= "number" or epoch ~= self._liveEpoch or self._retiring then
    return nil
  end
  local installed = self._cache[epoch]
  if installed == nil then
    return nil
  end
  local copy = {}
  for field, value in pairs(installed.identity) do
    copy[field] = value
  end
  return copy
end

-- Whether the selected epoch's installed sequence captured the first-play
-- fact. Only a committed installation can prove it: a live epoch that
-- installed nothing answers false, and a retired or unknown epoch answers
-- nothing at all.
---@param epoch integer
---@return boolean?
function CacheService:firstPlayReady(epoch)
  if type(epoch) ~= "number" then
    return nil
  end
  local installed = self._cache[epoch]
  if installed == nil then
    return epoch == self._liveEpoch and not self._retiring and false or nil
  end
  if epoch ~= self._liveEpoch or self._retiring then
    return nil
  end
  return installed.firstPlay == true
end

-- Ask the controller to record first play for the epoch. The request is
-- deduplicated per epoch: the controller proves the bounded first-play closure
-- before it records the fact, and repeating the call changes nothing.
---@param epoch integer
---@return boolean? true when the epoch lives, nil for a stale epoch
function CacheService:recordFirstPlay(epoch)
  if type(epoch) ~= "number" or epoch ~= self._liveEpoch or self._retiring then
    return nil
  end
  if self._failure ~= nil then
    return nil
  end
  if self._firstPlayRequested[epoch] then
    return true
  end
  self._firstPlayRequested[epoch] = true
  self._controls[#self._controls + 1] = { op = "record-first-play", epoch = epoch }
  return true
end

-- Authorize a source import behind an acknowledged quiescence barrier. The
-- acknowledgement is consumed exactly once: a second import needs a fresh
-- barrier.
---@param epoch integer
---@param barrier integer
---@return boolean ok
---@return string? refusal
function CacheService:importSource(epoch, barrier)
  local waiter = self._barriers[tostring(epoch) .. ":" .. tostring(barrier)]
  if waiter == nil or waiter.quiesce ~= true then
    return false, "no quiescence barrier authorizes the import"
  end
  if waiter.state ~= "ready" then
    return false, "no import crosses an unacknowledged quiescence barrier"
  end
  if waiter.consumed then
    return false, "the quiescence barrier authorized exactly one import"
  end
  waiter.consumed = true
  return true
end

-- Test-only transport injection: script a controller answer without a
-- thread. Production never calls this; it exists so composition tests can
-- drive barrier and readiness boundaries deterministically.
---@param packet table<string, unknown>
function CacheService:injectReply(packet)
  assert(type(packet) == "table", "injected reply must be a record")
  self._reply:push(packet)
end

---@param cause string?
function CacheService:_enterTerminalFailure(cause)
  if self._failure ~= nil then
    return
  end
  if cause == nil or cause == "" then
    cause = "controller thread exited"
  end
  self._failure = "controller thread stopped: " .. tostring(cause)
  self._controls = {}
  self._ordinary = {}
end

function CacheService:_checkWorkerHealth()
  if not self._started or self._joined or self._failure ~= nil then
    return
  end
  local worker = assert(self._worker, "cache controller thread is missing")
  if type(worker.isRunning) ~= "function" then
    return
  end
  local ok, running = pcall(function()
    return worker:isRunning()
  end)
  if ok and running then
    return
  end
  local cause = nil
  if not ok then
    cause = running
  elseif type(worker.getError) == "function" then
    local _, workerError = pcall(function()
      return worker:getError()
    end)
    cause = workerError
  end
  self:_enterTerminalFailure(cause)
end

---@param packet unknown
function CacheService:_absorb(packet)
  if type(packet) ~= "table" then
    return
  end
  local op = packet.op
  if op == "select-result" then
    self:_absorbSelectResult(packet)
  elseif op == "request-result" then
    self:_absorbRequestResult(packet)
  elseif op == "barrier-result" then
    self:_absorbBarrierResult(packet)
  elseif op == "boot-source-result" then
    self:_absorbBootSourceResult(packet)
  elseif op == "offer-source-result" then
    self:_absorbOfferSourceResult(packet)
  elseif op == "cache-install-begin" then
    self:_absorbInstallBegin(packet)
  elseif op == "cache-install-entries" then
    self:_absorbInstallEntries(packet)
  elseif op == "cache-install-commit" then
    self:_absorbInstallCommit(packet)
  elseif op == "controller-failure" then
    self:_enterTerminalFailure(packet.errorMessage)
  end
end

-- One installation stream belongs to the live epoch only: traffic for a
-- retired or unknown epoch is dropped with the references it carries.
---@param packet table<string, unknown>
---@return boolean live
function CacheService:_installTarget(packet)
  if packet.epoch ~= self._liveEpoch or self._retiring then
    return false
  end
  return self._failure == nil
end

---@param packet table<string, unknown>
function CacheService:_absorbInstallBegin(packet)
  if not self:_installTarget(packet) then
    return
  end
  local epoch = packet.epoch
  assert(isPositiveInteger(packet.sequence), "an installation sequence must be a positive integer")
  assert(type(packet.generationId) == "string" and packet.generationId ~= "", "an installation names its generation")
  assert(type(packet.identity) == "table", "an installation names the derived-cache identity")
  assert(type(packet.entryCount) == "number" and packet.entryCount >= 0, "an installation names its entry count")
  local installed = self._cache[epoch]
  if packet.initial ~= true then
    local expected = installed ~= nil and installed.sequence + 1 or 1
    assert(
      packet.sequence == expected,
      "an installation sequence must continue the stream: got "
        .. tostring(packet.sequence)
        .. ", expected "
        .. tostring(expected)
    )
  end
  self._install[epoch] = {
    sequence = packet.sequence,
    generationId = packet.generationId,
    identity = packet.identity,
    entryCount = packet.entryCount,
    parts = {},
  }
end

-- The pending installation whose sequence the part addresses, or nil when the
-- part is a replay of an already installed sequence.
---@param packet table<string, unknown>
---@return CacheService.Pending?
function CacheService:_installForPacket(packet)
  local pending = self._install[packet.epoch]
  if pending ~= nil and pending.sequence == packet.sequence then
    return pending
  end
  return nil
end

---@param packet table<string, unknown>
function CacheService:_absorbInstallEntries(packet)
  if not self:_installTarget(packet) then
    return
  end
  local epoch = packet.epoch
  local entries = packet.entries
  assert(type(entries) == "table", "an installation part carries its entries")
  assert(
    #entries <= INSTALL_PART_ENTRIES,
    "an installation part carries at most " .. INSTALL_PART_ENTRIES .. " entries"
  )
  assert(isPositiveInteger(packet.part), "an installation part names its position")
  local pending = self:_installForPacket(packet)
  if pending == nil then
    local installed = self._cache[epoch]
    assert(
      installed ~= nil and installed.sequence == packet.sequence,
      "an installation part addresses no pending sequence: " .. tostring(packet.sequence)
    )
    for index, entry in ipairs(entries) do
      local committed = assert(installed.store:resolveAsset(entry.path), "a replayed part names no installed entry")
      local expected = {
        path = committed.path,
        sourceId = committed.sourceId,
        contentId = committed.contentId,
        size = committed.size,
        data = committed.data,
      }
      assert(
        sameEntry(entry, expected),
        "a replayed installation part contradicts the installed bytes: " .. tostring(index)
      )
    end
    return
  end
  assert(pending.generationId == packet.generationId, "an installation part contradicts its generation")
  local received = pending.parts[packet.part]
  if received ~= nil then
    assert(#received == #entries, "a replayed installation part carries a different entry count")
    for index, entry in ipairs(entries) do
      assert(sameEntry(entry, received[index]), "a replayed installation part carries different bytes")
    end
    return
  end
  assert(packet.part == #pending.parts + 1, "an installation part arrived out of order: got " .. tostring(packet.part))
  local stored = {}
  for index, entry in ipairs(entries) do
    stored[index] = entry
  end
  pending.parts[packet.part] = stored
end

---@param packet table<string, unknown>
function CacheService:_absorbInstallCommit(packet)
  if not self:_installTarget(packet) then
    return
  end
  local epoch = packet.epoch
  local pending = self:_installForPacket(packet)
  assert(pending ~= nil, "an installation commit addresses no pending sequence: " .. tostring(packet.sequence))
  local entries = {}
  for part = 1, #pending.parts do
    for _, entry in ipairs(pending.parts[part]) do
      entries[#entries + 1] = entry
    end
  end
  assert(
    #entries == pending.entryCount,
    "an installation commit carries " .. tostring(#entries) .. " of " .. tostring(pending.entryCount) .. " entries"
  )

  -- Prepare the whole batch against the epoch store before anything visible
  -- changes: a refused batch leaves the installed view exactly as it was.
  local installed = self._cache[epoch]
  local store = installed ~= nil and installed.store
    or ResidentCache.new(self:_versionOfEpoch(epoch), BASE_SOURCE_PREFIX .. pending.generationId)
  local prepared = store:prepare(entries)
  store:commit(prepared)
  local reader = installed ~= nil and installed.reader or CacheFs.fromStore(store)
  local milestones = installed ~= nil and installed.milestones or {}
  if type(packet.milestones) == "table" then
    for _, name in ipairs(packet.milestones) do
      assert(type(name) == "string" and name ~= "", "an installed milestone fact needs its name")
      milestones[name] = true
    end
  end
  self._cache[epoch] = {
    generationId = pending.generationId,
    identity = pending.identity,
    store = store,
    reader = reader,
    sequence = pending.sequence,
    firstPlay = packet.firstPlay == true or (installed ~= nil and installed.firstPlay),
    milestones = milestones,
  }
  self._install[epoch] = nil
  self._generations[epoch] = pending.generationId
  for name in pairs(milestones) do
    self:_settleMilestone(epoch, name)
  end
  self:_settleObservations(epoch)
end

-- An installed milestone fact proves its own captured closure: the matching
-- milestone request settles without waiting for a separate terminal packet.
---@param epoch integer
---@param name string
function CacheService:_settleMilestone(epoch, name)
  if epoch ~= self._liveEpoch or self._retiring then
    return
  end
  local id = self._byKey[tostring(epoch) .. ":milestone:" .. name]
  if id == nil then
    return
  end
  local record = self._records[id]
  if record == nil or record.terminal then
    return
  end
  -- A buffered terminal fact is the authoritative answer for this request: it
  -- keeps the request pending until the sequence it names is installed.
  local buffered = self._pendingObservations[epoch]
  if buffered ~= nil and buffered[id] ~= nil then
    return
  end
  record.terminal = true
  record.ready = true
  record.failure = nil
end

-- The worker-visible version of the selected epoch. The store keeps it for its
-- own diagnostics; installation packets carry no version id of their own.
---@param epoch integer
---@return string
function CacheService:_versionOfEpoch(epoch)
  local version = self._versions[epoch]
  assert(type(version) == "string", "the installing epoch has no selected version")
  return version
end

-- Expose every buffered terminal fact whose bytes are now installed. Each
-- fact settles once, through the same record path an immediate fact uses.
---@param epoch integer
function CacheService:_settleObservations(epoch)
  local buffered = self._pendingObservations[epoch]
  if buffered == nil then
    return
  end
  local installed = assert(self._cache[epoch], "a settled observation needs its installed sequence")
  for requestId, packet in pairs(buffered) do
    local required = packet.requiredSequence
    if required == nil or required <= installed.sequence then
      buffered[requestId] = nil
      self:_applyRequestResult(packet)
    end
  end
  if next(buffered) == nil then
    self._pendingObservations[epoch] = nil
  end
end

-- A pushed terminal request fact lands only in its exact record: the
-- packet epoch must be live and the request identity must belong to it.
-- Stale or unknown results are ignored.
-- A pushed boot-gate fact lands only in its exact live record: the packet
-- epoch must be live and the boot observation still pending. A rejected
-- source offer already failed the epoch, so no later success can overwrite
-- it; duplicates and stale replies are ignored.
---@param packet table<string, unknown>
function CacheService:_absorbBootSourceResult(packet)
  if packet.epoch ~= self._liveEpoch or self._retiring then
    return
  end
  local record = self._boot[packet.epoch]
  if record == nil or record.state ~= "pending" then
    return
  end
  if packet.state == "ready" then
    record.state = "ready"
    record.detail = nil
  elseif packet.state == "source-required" or packet.state == "failed" then
    record.state = packet.state
    if type(packet.detail) == "table" then
      record.detail = packet.detail
    else
      record.detail = { code = "SOURCE_UNAVAILABLE", message = tostring(packet.detail) }
    end
  end
end

-- A pushed source-offer acknowledgement lands only in its exact live
-- record. Acceptance leaves the pending gate alone; a rejection fails the
-- epoch with its observable cause and no later gate answer can clear it.
---@param packet table<string, unknown>
function CacheService:_absorbOfferSourceResult(packet)
  if packet.epoch ~= self._liveEpoch or self._retiring then
    return
  end
  if packet.ok == true then
    return
  end
  local record = self._boot[packet.epoch]
  if record == nil or record.state ~= "pending" then
    return
  end
  local cause = packet.errorMessage
  if cause == nil or cause == "" then
    cause = "the controller refused the source offer"
  end
  record.state = "failed"
  record.detail = { code = "SOURCE_OFFER_REJECTED", message = tostring(cause) }
end

---@param packet table<string, unknown>
function CacheService:_absorbRequestResult(packet)
  if packet.epoch ~= self._liveEpoch or self._retiring then
    return
  end
  local required = packet.requiredSequence
  local installed = self._cache[packet.epoch]
  if required ~= nil and (installed == nil or installed.sequence < required) then
    -- The fact may not overtake the bytes it vouches for.
    local epoch = packet.epoch
    local buffered = self._pendingObservations[epoch]
    if buffered == nil then
      buffered = {}
      self._pendingObservations[epoch] = buffered
    end
    buffered[packet.requestId] = packet
    return
  end
  self:_applyRequestResult(packet)
end

---@param packet table<string, unknown>
function CacheService:_applyRequestResult(packet)
  if packet.epoch ~= self._liveEpoch or self._retiring then
    return
  end
  local record = self._records[packet.requestId]
  if record == nil or record.epoch ~= self._liveEpoch or record.terminal then
    return
  end
  if packet.state == "ready" then
    record.terminal = true
    record.ready = true
    record.failure = nil
  elseif packet.state == "failed" then
    record.terminal = true
    record.ready = false
    record.failure = packet.errorMessage or packet.errorCode
  end
end

-- A pushed barrier fact settles only its exact waiter: epoch, barrier
-- identity, and kind must all match. An older identity never satisfies a
-- newer waiter by ordering alone.
---@param packet table<string, unknown>
function CacheService:_absorbBarrierResult(packet)
  local waiter = self._barriers[tostring(packet.epoch) .. ":" .. tostring(packet.barrierId)]
  if waiter == nil or waiter.state ~= "pending" then
    return
  end
  if packet.kind == "quiesce" then
    if waiter.quiesce ~= true then
      return
    end
  elseif packet.kind == "retire" then
    if waiter.quiesce == true then
      return
    end
  else
    return
  end
  waiter.state = "ready"
  if packet.kind == "retire" and waiter.epoch == self._liveEpoch and self._retiring then
    self._liveEpoch = nil
    self._retiring = false
  end
end

---@param packet table<string, unknown>
function CacheService:_absorbSelectResult(packet)
  if packet.epoch ~= self._liveEpoch or self._retiring then
    return
  end
  if packet.ok ~= true then
    local message = packet.errorMessage
    if message == nil or message == "" then
      message = "controller selection failed"
    end
    self:_enterTerminalFailure(message)
    return
  end
  -- The controller-derived generation token is the canonical identity for
  -- durability decisions (first-play completion): it already reflects the
  -- ROM SHA, producer identity/mode, asset revision, and script API the
  -- game thread must never re-derive by scanning sources.
  if type(packet.generationId) == "string" and packet.generationId ~= "" then
    self._generations[packet.epoch] = packet.generationId
  end
end

---@return table<string, integer> emitted counts for the frame
function CacheService:_emit()
  local sent = { ordinary = 0 }
  for _, command in ipairs(self._controls) do
    self._command:push(command)
  end
  self._controls = {}
  for _, command in ipairs(self._ordinary) do
    if sent.ordinary >= ORDINARY_PER_UPDATE then
      break
    end
    self._command:push(command)
    local record = self._records[command.requestId]
    if record ~= nil then
      record.sent = true
    end
    sent.ordinary = sent.ordinary + 1
  end
  if sent.ordinary >= #self._ordinary then
    self._ordinary = {}
  else
    local waiting = {}
    for position = sent.ordinary + 1, #self._ordinary do
      waiting[#waiting + 1] = self._ordinary[position]
    end
    self._ordinary = waiting
  end
  return sent
end

-- Pump the transport once: absorb a bounded batch of pushed terminal
-- events, then emit at most eight queued ordinary records. Never blocks,
-- never performs producer or filesystem work.
---@return table<string, integer> emitted counts for the frame
function CacheService:update()
  self:_checkWorkerHealth()
  local absorbed = 0
  while absorbed < ABSORB_PER_UPDATE do
    local packet = self._reply:pop()
    if packet == nil then
      break
    end
    absorbed = absorbed + 1
    self:_absorb(packet)
  end
  if self._failure ~= nil then
    return { ordinary = 0 }
  end
  return self:_emit()
end

-- Join the controller thread exactly once. Process shutdown alone joins;
-- selection retirement never does. Unsent interest is discarded: shutdown
-- is final and nothing after it can observe this process.
function CacheService:shutdown()
  if self._joined then
    return
  end
  self._joined = true
  self._controls = {}
  self._ordinary = {}
  for epoch in pairs(self._cache) do
    self:_revokeEpoch(epoch)
  end
  if not self._started then
    return
  end
  pcall(function()
    self._command:push({ op = "shutdown" })
  end)
  local worker = self._worker
  if worker ~= nil and type(worker.wait) == "function" then
    pcall(function()
      worker:wait()
    end)
  end
end

return CacheService
